export const meta = {
  name: 'epic-4-triage',
  description: 'Read-only triage of epic #4 children (#390-#394) against current main',
  phases: [{ title: 'Triage' }],
}
const TRIAGE = {
  type: 'object',
  properties: {
    items: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          repo: { type: 'string' },
          issue: { type: 'number' },
          title: { type: 'string' },
          status: { type: 'string', enum: ['done', 'partial', 'open', 'needs-ruling'] },
          evidence: { type: 'string' },
          remaining: { type: 'string' },
          implementable: { type: 'boolean' },
          priority: { type: 'number' },
          files: { type: 'string' },
        },
        required: ['repo', 'issue', 'title', 'status', 'evidence', 'remaining', 'implementable', 'priority', 'files'],
      },
    },
  },
  required: ['items'],
}
const PRE = `Repo pmatos/forseti at /home/pmatos/dev/forseti, epic #4 (W3 differential grading harness: score a property by 'holds on real code AND breaks on mutants'). READ-ONLY triage: do not post comments, close issues, change code, or create worktrees/PRs; run reproducers only in a scratch dir. Read CLAUDE.md (vocabulary: verdicts not proofs; ESBMC bounded). Run git fetch and read from origin/main.`
const BRIEF = (theme, issues, extra) => `${PRE}
Theme '${theme}': issues ${issues}. For each: read the body and every comment (gh issue view N --comments), the code, tests, docs (docs/design/0006, 0007, docs/adr/0009, docs/roadmap.md) it names, and test its claims against current origin/main. Classify done | partial | open | needs-ruling with concrete evidence, the precise remaining work, whether an agent can do it without a ruling, a priority (1 = blocks the epic gate, 3 = nice to have), and the files a fix would touch (so the orchestrator can decide parallel vs serial). Note dependencies between issues and any design ambiguity that needs a human ruling. ${extra}`
const THEMES = [
  { theme: 'mutation+equivalence', issues: '#390, #391', extra: 'Check what in src/forseti/properties/harness.py (renderability_reason, function-body locator #163), src/forseti/precond/synth.py and src/forseti/esbmc already exists that the mutation kit and the f__ref/f equivalence harness can reuse. Suggest module placement (a new small package such as src/forseti/grading/ per the roadmap).' },
  { theme: 'grading+vacuity+discrimination', issues: '#392, #393, #394', extra: 'Check PropertyOutcome, check_properties/PropertyCheckRun.held() in src/forseti/orchestrator/check.py, property_gate.py, precond/reachability.py, properties/store.py (Grading, update_status GRADED gap), core CLI/MCP. Report the dependency order (#392 depends on #390,#391,#393; #394 depends on #393) and whether #393 can ship first independently. Also check whether #387 (struct invariant) has landed.' },
]
const results = await Promise.all(THEMES.map(async t => {
  try {
    const triage = await agent(BRIEF(t.theme, t.issues, t.extra), { schema: TRIAGE, effort: 'medium', label: 'triage:' + t.theme })
    if (triage && Array.isArray(triage.items)) return { theme: t.theme, triage, incomplete: false }
  } catch (e) { log('Triage theme threw: ' + t.theme) }
  log('Incomplete triage theme: ' + t.theme)
  return { theme: t.theme, triage: null, incomplete: true }
}))
return results

