export const meta = {
  name: 'epic-4-wave1-fix',
  description: 'Epic #4 wave 1: #390 mutation kit, #391 equivalence harness, #393 vacuity guard -> PRs at READY (no merges)',
  phases: [{ title: 'Implement' }, { title: 'Review' }, { title: 'Simplify' }, { title: 'Checks' }],
}
const STAGE = {
  type: 'object',
  properties: {
    repo: { type: 'string' },
    issue: { type: 'number' },
    pr: { type: 'number' },
    branch: { type: 'string' },
    worktree: { type: 'string' },
    sha: { type: 'string' },
    checks: { type: 'array', items: { type: 'string' } },
    needsRuling: { type: 'string' },
    notes: { type: 'string' },
  },
  required: ['repo', 'issue', 'pr', 'branch', 'worktree', 'sha', 'checks', 'needsRuling', 'notes'],
}
const PRE = `Repo pmatos/forseti at /home/pmatos/dev/forseti, epic #4 (W3 differential grading: score a property by 'holds on real code AND breaks on mutants'). Read CLAUDE.md and the docs it links; vocabulary discipline matters (verdicts, not proofs; ESBMC is bounded; UNKNOWN is never silently passed). Work in your OWN git worktree, never the main checkout: git fetch origin; git worktree add --no-track /tmp/claude-1000/-home-pmatos-dev-forseti/3c845eae-9d6b-46ab-bd1c-824db85dcc42/scratchpad/wt-<N> -b vibe/<N>-<slug> origin/main (reuse it if it exists). A fresh worktree has no venv: run 'uv venv && uv pip install -e ".[dev]"' inside it and verify python -c 'import forseti; print(forseti.__file__)' points into the worktree. Commit as Paulo Matos <p@ocmatos.com>, following the repo's commit and PR-title rules (Conventional Commits, see commitlint config and .github/workflows/lint-pr-title.yml). Publish with git push -u origin HEAD; never plain --force, never rebase (the orchestrator rebases when needed), never --no-verify/SKIP, stage explicit paths (never git add -A), kill processes by recorded PID only. The repo comment style: comment sparingly, only complex code. Do not change gate thresholds, baselines, snapshots or ADRs (ADRs are immutable once Accepted; add a new ADR only if a decision truly needs one). PR body says 'Part of #4' for the epic and 'Part of #<N>' for the issue: NEVER write a closing keyword (close/fix/resolve) next to any issue number; the orchestrator closes issues after verifying. Do not merge. Run targeted tests locally while developing, but 'green' means every required check (CI test, Lint commits, Lint PR title, Workflow Lint) on the final head SHA completed successfully on GitHub; report anything older than your last push as not run. Another agent works in parallel on sibling issues in the same package area, so keep your diff scoped to your issue and avoid gratuitous edits to shared files.`
const ISSUES = [
  {
    n: 390, slug: 'mutation-kit',
    plan: `Issue #390 'W3.1 Mutation operator kit'. Read the issue body (gh issue view 390) and its acceptance list; triage found nothing exists on main. Plan: new package src/forseti/grading/ (mutate.py, possibly body.py). Reusable: esbmc/units.py::find_definition_brace (opening brace of the target body; masks comments/strings via private _stripped_for_scan), list_units/parse_units as compile-validity oracle (a mutant that fails to parse is dropped and counted, never scored), properties/harness.py::_nondet_slug for havoc nondet types. Gaps to fill: a body-span locator (brace match on masked source; expose a small public additive helper rather than importing a private), a token-level scanner over the body, frozen Mutant dataclass (id = operator,line,column,ordinal; mutated source; one-line description like '< -> <= at line 12'), five v1 operators (relational flip, +/- swap, +-1 on integer constants/bounds, drop an 'if (c) return ...;' guard, havoc an output via nondet), deterministic order (offset then operator order), optional cap with fixed seed, returns (mutants, dropped_count). Mutate only inside the target function body; the rest of the TU stays byte-identical. Do not add operators beyond the v1 list. Tests: per-operator unit tests, a golden determinism test, no-mutant-touches-outside-target test, ESBMC-gated test that on each examples/ kernel every applicable operator yields >=1 mutant and every emitted mutant compiles, and that rb_push's mutants include the ring_buffer_bug.c change (dropped 'count == CAP' guard). ESBMC-gated tests must skip when esbmc is not on PATH (follow existing marker/skip idiom in tests/). Also fix the stale src/grading/ path in docs/roadmap.md only if trivially in scope, and add a one-line mention in src/README.md if the repo convention lists packages.`,
  },
  {
    n: 391, slug: 'equivalence-harness',
    plan: `Issue #391 'W3.2 Equivalence harness (RFC-0006 S1) and equivalent-mutant filter'. Read the issue, docs/design/0006-positioning-specs-from-existing-artifacts.md sections 2-3, docs/adr/0009. Triage found nothing exists on main. Plan: src/forseti/grading/equivalence.py (the grading package is created concurrently by the #390 agent: if src/forseti/grading/__init__.py is not on origin/main when you start, create a minimal one; if both PRs add it the orchestrator resolves the trivial conflict). Reusable: esbmc/units.py::rename_all_declarations_and_definitions(source,'f','f__ref'); properties/harness.py emission recipe (render_semantic_harness, _nondet_slug/_nondet_ctypes, _render_buffer, _call_arg, _is_scalar_backed, HarnessError); esbmc.runner.verify + counterexample parser for the witness. Another agent (#393) edits properties/harness.py concurrently, so DO NOT modify harness.py beyond what is strictly needed (prefer importing existing names; if you must promote a private helper, make a minimal behaviour-identical change). Build: render_equivalence_harness (one TU with f__ref and f; main draws nondet inputs once, gives each version its own copy of every input buffer, calls both, asserts equality of the return value and every output buffer), check_equivalence -> typed result VERIFIED / VIOLATED with behaviour-diff witness (input, reference output, candidate output) / UNKNOWN (never silently passed; carry k and length bounds), and filter_equivalent(original, mutants, k) -> kept, skipped_equivalent, skipped count (the count is always reported: a mutant diverging only beyond k is skipped too, which inflates kill-rate; document that bias). Relation: bitwise equality; floats = both NaN or bit-identical so NaN and -0.0 are handled. Refusals with a reason, never guessing: anything renderability_reason does not accept, AND the confirmed gap that struct-pointer args (e.g. examples/ring_buffer.c::rb_push, ring_t*) and mis-typed shapes (examples/merge_sort.c::msort) are not refused today, plus units that write globals (v1 refuses; fail closed), mismatched ref/candidate signatures, a main() in either source. Interface for the mutation kit (#390): filter_equivalent should accept any sequence of objects exposing a .source string and an .id (use a small Protocol) so it composes with #390's Mutant without importing it. Out of scope: gate integration, an EQUIVALENCE property kind. Tests: unit tests for renderer text without ESBMC; ESBMC-gated tests (skip without esbmc) for: one-input-diff fixture pair VIOLATED with that input as witness; semantics-preserving rewrite VERIFIED up to k; float fixture for -0.0/+0.0 and NaN; skipped (equivalent) mutants reported separately via the filter. Local esbmc may be 8.3.0 vs CI's pinned version: do not depend on version-specific output text.`,
  },
  {
    n: 393, slug: 'vacuity-guard',
    plan: `Issue #393 'W3.4 Vacuity guard'. Read the issue and ADR-0009 (D2 and Consequences: additive PropertyOutcome values). Triage found: properties/harness.py::render_semantic_harness emits only __ESBMC_assert((post), "forseti:semantic") after the call; orchestrator/check.py::_outcome_for maps Verified -> HELD unconditionally; PropertyOutcome has held/violated/unknown/error/skipped; precond/reachability.py::classify_site_probe (REACHED/UNREACHABLE/INCONCLUSIVE, needs a non-empty label) and precond/synth.py (NON_VACUITY_LABEL='forseti:non-vacuity', the one probe emitter) are reusable. Build: (1) a probe render mode in properties/harness.py: same body and same k, with a labelled __ESBMC_assert(0, label) after the call and the real assertion omitted; share the label constant / emit helper with precond/synth.py if it is small and behaviour-identical. (2) In check_properties, after a VERIFIED (HELD) verdict at its settled k, run the probe at the same k: REACHED -> HELD, UNREACHABLE -> new PropertyOutcome.VACUOUS, INCONCLUSIVE -> UNKNOWN. Never probe VIOLATED/UNKNOWN/ERROR. (3) Add PropertyOutcome.VACUOUS additively, and handle every consumer: PropertyCheckRun._outcome_for_counts (a vacuous result must never produce run-outcome 'held'; pick and document precedence), to_dict, adapters/claude_code/property_gate.py (vacuous never counts toward acceptance and must be surfaced, not silently dropped), core/check.py, core/cli.py (exit-code mapping and docstrings enumerating outcomes), core/mcp_server.py (payload/docs), core/loop.py if it reads outcomes. (4) Output states the limitation: the probe shows some path reaches the post-call point; it does not show that k covers every path (paths cut by --no-unwinding-assertions can still hide a violation). (5) Tests: fake-port unit tests; ESBMC-gated (skip without esbmc): domain 'x > 0 && x < 0' -> vacuous not HELD; a unit whose loop needs more than k iterations on every input -> vacuous at that k; existing HELD results on examples/ stay HELD (or explain); gate test that vacuous never counts toward acceptance. Do not change the unwind/k policy or any threshold. If a vacuous-vs-run-outcome naming choice is a real design call, take the additive minimal option, document it in the PR, and put the question in needsRuling rather than stalling.`,
  },
]
const results = await pipeline(
  ISSUES,
  it => agent(`${PRE}

TASK (stage 1 of 4: implement). ${it.plan}

Run /investigate ${it.n} in your worktree: it takes the issue to an open PR (reproduce or design, implement with tests, commit, push, open the PR). Overrides: the PR body says 'Part of #4' and 'Part of #${it.n}', never a closing keyword. If it stops on a blocker (ambiguous design), open no PR and report it in needsRuling (use pr=0). Return the stage result: pr number, branch, worktree path, head sha, checks as 'name: state' strings (may be pending), needsRuling, notes. Do not wait for CI in this stage.`,
    { schema: STAGE, phase: 'Implement', label: 'impl:#' + it.n }),
  (r, it) => {
    if (!r || !r.pr) return r
    return agent(`${PRE}

TASK (stage 2 of 4: review). Existing PR #${r.pr} for issue #${it.n} on branch ${r.branch}; worktree ${r.worktree} (recreate with git worktree add -B ${r.branch} <dir> origin/${r.branch} if gone; check 'gh pr list --state all --search "#${it.n}"' first). Run /code-review high --fix --comment on the PR from the worktree. Commit the applied fixes (explicit paths) and push. The review output is one step: continue after it. Return the stage result with the new head sha.`,
      { schema: STAGE, phase: 'Review', label: 'review:#' + it.n })
  },
  (r, it) => {
    if (!r || !r.pr) return r
    return agent(`${PRE}

TASK (stage 3 of 4: simplify). PR #${r.pr} for issue #${it.n} on branch ${r.branch}; worktree ${r.worktree} (recreate if gone, as above). Run /simplify from the worktree, then commit and push what it applied (explicit paths); if it changed nothing, say so. The output is one step: continue after it. Return the stage result with the new head sha.`,
      { schema: STAGE, phase: 'Simplify', label: 'simplify:#' + it.n })
  },
  (r, it) => {
    if (!r || !r.pr) return r
    return agent(`${PRE}

TASK (stage 4 of 4: checks to READY). PR #${r.pr} for issue #${it.n} on branch ${r.branch}; worktree ${r.worktree}. Wait for every required check to complete on the FINAL head SHA of the PR branch (git fetch; gh pr view ${r.pr} --json headRefOid,statusCheckRollup). Wait in the FOREGROUND with blocking calls of at most ~10 minutes each (timeout 600 gh pr checks ${r.pr} --watch), repeated until all checks complete; never end your turn while checks are pending. If a check fails, read the log (gh run view --log-failed for that run only), fix with the smallest change, commit, push, and wait again on the new head. Do not regenerate baselines or change thresholds to pass. Do not merge. Return READY: pr, branch, sha (the PR's final head), checks as 'name: conclusion' for every check on that sha, needsRuling, notes (anything not green and why).`,
      { schema: STAGE, phase: 'Checks', label: 'checks:#' + it.n })
  },
)
return results
